args.content:
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  color: #e0e0e0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
}

.game {
  text-align: center;
}

h1 {
  margin: 0 0 8px;
  font-size: 2rem;
  letter-spacing: 4px;
  color: #4caf50;
}

.score {
  margin-bottom: 12px;
  font-size: 1.2rem;
}

canvas {
  background: #0f0f1a;
  border: 3px solid #4caf50;
  border-radius: 6px;
  display: block;
  margin: 0 auto;
}

.overlay {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.75);
}

.overlay.hidden {
  display: none;
}

.gameover {
  font-size: 3rem;
  margin-bottom: 24px;
  color: #ff5252;
}

button {
  font-size: 1.1rem;
  padding: 12px 28px;
  border: none;
  border-radius: 6px;
  background: #4caf50;
  color: #fff;
  cursor: pointer;
}

button:hover {
  background: #43a047;
}

.hint {
  margin-top: 16px;
  font-size: 0.9rem;
  opacity: 0.6;
}

(() => {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const scoreEl = document.getElementById("score");
  const overlay = document.getElementById("overlay");
  const restartBtn = document.getElementById("restart");

  const CELL = 20;
  const COLS = canvas.width / CELL; // 20
  const ROWS = canvas.height / CELL; // 20

  let snake, dir, nextDir, food, score, loop, running;

  function reset() {
    snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = score;
    placeFood();
    overlay.classList.add("hidden");
    running = true;
    if (loop) clearInterval(loop);
    loop = setInterval(tick, 100);
  }

  function placeFood() {
    let pos;
    do {
      pos = {
        x: Math.floor(Math.random() * COLS),
        y: Math.floor(Math.random() * ROWS),
      };
    } while (snake.some((s) => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function tick() {
    if (!running) return;
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    // Wall collision
    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) {
      return gameOver();
    }
    // Self collision
    if (snake.some((s) => s.x === head.x && s.y === head.y)) {
      return gameOver();
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 1;
      scoreEl.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function draw() {
    ctx.fillStyle = "#0f0f1a";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Food
    ctx.fillStyle = "#ff5252";
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    // Snake
    ctx.fillStyle = "#4caf50";
    for (const segment of snake) {
      ctx.fillRect(segment.x * CELL, segment.y * CELL, CELL, CELL);
    }
  }

  function gameOver() {
    running = false;
    if (loop) clearInterval(loop);
    draw();
    overlay.classList.remove("hidden");
  }

  function setDirection(x, y) {
    // Prevent reversing directly into itself
    if (x === -dir.x && y === -dir.y) return;
    nextDir = { x, y };
  }

  document.addEventListener("keydown", (e) => {
    switch (e.key) {
      case "ArrowUp": setDirection(0, -1); break;
      case "ArrowDown": setDirection(0, 1); break;
      case "ArrowLeft": setDirection(-1, 0); break;
      case "ArrowRight": setDirection(1, 0); break;
      default: return; // ignore other keys
    }
    e.preventDefault();
  });

  restartBtn.addEventListener("click", reset);

  reset();
  draw();
})();
